public class Main {
    static class BankAccount {
        private int balance;
        BankAccount(int openingBalance) { balance = Math.max(0, openingBalance); }
        boolean deposit(int amount) {
            if (amount <= 0) return false;
            balance += amount; return true;
        }
        boolean withdraw(int amount) {
            if (amount <= 0 || amount > balance) return false;
            balance -= amount; return true;
        }
        int getBalance() { return balance; }
    }
    public static void main(String[] args) {
        BankAccount account = new BankAccount(1000);
        account.deposit(250);
        account.withdraw(400);
        System.out.println("Balance: " + account.getBalance());
    }
}

public class Main {
    static class StudentResult {
        private final int a, b, c;
        StudentResult(int a, int b, int c) {
            this.a = valid(a); this.b = valid(b); this.c = valid(c);
        }
        private int valid(int mark) {
            if (mark < 0 || mark > 100) throw new IllegalArgumentException("Invalid mark");
            return mark;
        }
        double average() { return (a + b + c) / 3.0; }
        String grade() {
            double avg = average();
            if (avg >= 80) return "A";
            if (avg >= 60) return "B";
            if (avg >= 40) return "C";
            return "F";
        }
    }
    public static void main(String[] args) {
        StudentResult result = new StudentResult(80, 70, 90);
        System.out.printf("Average: %.2f%nGrade: %s%n", result.average(), result.grade());
    }
}

