public class Main {
    static class BankAccount {
        private int balance;
        BankAccount(int balance) { this.balance = Math.max(0, balance); }
        boolean transferTo(BankAccount other, int amount) {
            if (other == null || other == this || amount <= 0 || amount > balance) return false;
            balance -= amount;
            other.balance += amount;
            return true;
        }
        int getBalance() { return balance; }
    }
    public static void main(String[] args) {
        BankAccount a = new BankAccount(900);
        BankAccount b = new BankAccount(100);
        System.out.println("Success: " + a.transferTo(b, 300));
        System.out.println("Source: " + a.getBalance());
        System.out.println("Destination: " + b.getBalance());
    }
}

