public class Main {
    static class Rectangle {
        int left, bottom, width, height;
        Rectangle(int left, int bottom, int width, int height) {
            if (width <= 0 || height <= 0) throw new IllegalArgumentException("Dimensions must be positive");
            this.left = left; this.bottom = bottom; this.width = width; this.height = height;
        }
        boolean overlaps(Rectangle r) {
            return left < r.left + r.width && left + width > r.left
                && bottom < r.bottom + r.height && bottom + height > r.bottom;
        }
    }
    public static void main(String[] args) {
        Rectangle a = new Rectangle(0, 0, 4, 3);
        Rectangle b = new Rectangle(3, 1, 2, 2);
        System.out.println("Overlap: " + a.overlaps(b));
    }
}

