public class Main {
    static class Interval {
        int start, end;
        Interval(int start, int end) {
            if (start > end) throw new IllegalArgumentException("start must not exceed end");
            this.start = start; this.end = end;
        }
    }
    public static void main(String[] args) {
        Interval a = new Interval(1, 5), b = new Interval(5, 8);
        int start = Math.min(a.start, b.start);
        int end = Math.max(a.end, b.end);
        if (a.end < b.start || b.end < a.start) {
            Interval first = a.start <= b.start ? a : b;
            Interval second = first == a ? b : a;
            System.out.println("[" + first.start + "," + first.end + "] [" + second.start + "," + second.end + "]");
        } else {
            System.out.println("[" + start + "," + end + "]");
        }
    }
}

import java.util.List;
public class Main {
    static class Product {
        String name; int price;
        Product(String name, int price) {
            if (price < 0) throw new IllegalArgumentException("Negative price");
            this.name = name; this.price = price;
        }
    }
    static class CartItem {
        Product product; int quantity;
        CartItem(Product product, int quantity) {
            if (product == null || quantity <= 0) throw new IllegalArgumentException("Invalid cart item");
            this.product = product; this.quantity = quantity;
        }
        long subtotal() { return (long) product.price * quantity; }
    }
    public static void main(String[] args) {
        List<CartItem> cart = List.of(
            new CartItem(new Product("Book", 500), 2),
            new CartItem(new Product("Pen", 20), 3)
        );
        long total = 0;
        for (CartItem item : cart) total += item.subtotal();
        System.out.println("Total: " + total);
    }
}

