import java.util.HashSet;
import java.util.Objects;
import java.util.Set;
public class Main {
    static class EmployeeKey {
        private final String department;
        private final int employeeId;
        EmployeeKey(String department, int employeeId) {
            this.department = Objects.requireNonNull(department);
            this.employeeId = employeeId;
        }
        @Override public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof EmployeeKey)) return false;
            EmployeeKey other = (EmployeeKey) obj;
            return employeeId == other.employeeId && department.equals(other.department);
        }
        @Override public int hashCode() { return Objects.hash(department, employeeId); }
    }
    public static void main(String[] args) {
        Set<EmployeeKey> keys = new HashSet<>();
        keys.add(new EmployeeKey("Engineering", 42));
        System.out.println(keys.contains(new EmployeeKey("Engineering", 42)));
        System.out.println(keys.contains(new EmployeeKey("Sales", 42)));
    }
}

import java.util.List;
public class Main {
    interface DeliveryOption {
        int cost();
        String name();
    }
    static class StandardDelivery implements DeliveryOption {
        public int cost() { return 60; }
        public String name() { return "Standard"; }
    }
    static class ExpressDelivery implements DeliveryOption {
        public int cost() { return 100; }
        public String name() { return "Express"; }
    }
    public static void main(String[] args) {
        int budget = 100;
        List<DeliveryOption> options = List.of(new StandardDelivery(), new ExpressDelivery());
        DeliveryOption best = null;
        for (DeliveryOption option : options) {
            if (option.cost() <= budget && (best == null || option.cost() < best.cost()
                || (option.cost() == best.cost() && option.name().compareTo(best.name()) < 0))) {
                best = option;
            }
        }
        System.out.println(best == null ? "No option within budget" : best.name() + ": " + best.cost());
    }
}
